/**
 * Badge sets, built from the shared catalog (src/data/badgeCatalog.generated.js, same content as
 * backend/lib/badge_catalog.json, generated by scripts/build-badge-catalog.mjs). The server decides what is earned; this file only describes how to show it.
 *
 * Objective badges are one tier (earned = silver). The module badge (gold) is earned when enough of the module's
 * objective badges are. Math Refresher badges also have a Mastery Check: practice (bronze) -> mastered (silver).
 * Students see "unverified" and "confirmed" the same way; only instructors can tell them apart.
 */
import catalog from './badgeCatalog.generated.js'

export const BADGE_SETS = catalog.modules.map((m) => ({
  id: m.id,
  moduleId: m.id,
  classId: m.class_id,
  title: m.title,
  fullTitle: m.full_title || m.title,
  kind: m.kind,
  practicePath: m.path,
  moduleBadge: {
    awardId: m.module_badge.award_id,
    name: m.module_badge.name,
    glyph: m.module_badge.glyph,
    minCount: m.module_badge.min_count
  },
  topics: m.topics.map((t) => ({
    awardId: t.award_id,
    objectiveId: t.objective_id,
    name: t.name,
    glyph: t.glyph
  }))
}))

export function badgeSetForModule(moduleId) {
  return BADGE_SETS.find((s) => s.moduleId === moduleId) || null
}

/** What a student sees for an award state. */
export function studentTier(state) {
  if (state === 'earned' || state === 'confirmed' || state === 'unverified') return 'mastered'
  if (state === 'practice') return 'practice'
  return 'locked'
}

export function tierLabel(tier) {
  return tier === 'mastered' ? 'Mastered' : tier === 'practice' ? 'Practice mastered' : 'Locked'
}

/** Progress for one set: how many objective badges are earned, and whether the module badge is. */
export function setProgress(set, awards) {
  const byId = Object.fromEntries((awards || []).map((a) => [a.award_id, a]))
  const earned = set.topics.filter((t) => studentTier(byId[t.awardId]?.state) === 'mastered').length
  const moduleEarned = studentTier(byId[set.moduleBadge.awardId]?.state) === 'mastered'
  return { earned, total: set.topics.length, moduleEarned }
}
